import{z as s,x as A,o as t,c as p,q as l,j as o,D as E,d as r,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"化学放大胶","description":"","frontmatter":{"title":"化学放大胶","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/car-resist.md","filePath":"litho/car-resist.md","lastUpdated":1791063341000}'),d={name:"litho/car-resist.md"};function h(m,a,D,P,c,C){const i=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=l('<h1 id="化学放大胶" tabindex="-1">化学放大胶 <a class="header-anchor" href="#化学放大胶" aria-label="Permalink to &quot;化学放大胶&quot;">​</a></h1><div class="epigraph"><p>一个吸收事件点燃一条产酸链，后烘里酸催化许多次脱保护：灵敏度靠化学增益买，不是靠把空中像再照亮一档。</p><footer>—— 据 Ito / Willson 化学放大思路，以及 Mack 对 CAR 产线链路的表述整理</footer></div><p><a href="/litho/dnq-novolac">上一课</a>（DNQ–Novolac 胶）。在此之上，工具写成能把空中像扫到晶圆上。缺口是记录介质：扫描狭缝留下的是剂量，还不是线条。本课引入化学放大胶（CAR）——DUV 的默认正胶家族。产酸剂与淬灭剂这一对旋钮怎么配，留给<a href="/litho/pag-quencher">下一课</a>；酸在膜里走多远、如何变成线宽粗糙度，是后面的<a href="/litho/acid-diffusion-lwr">酸扩散与线宽粗糙度</a>一课；显影衬度曲线再往后。不要在这里重讲扫描同步。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KrF / ArF 的光子能量比 g/i 线高，老式 DNQ–酚醛的吸收和量子产率撑不住薄膜灵敏度：胶要薄（以免吸收把底部吃黑），又要够敏（以免扫描慢到没有产能）。缺口因此是一种增益机制：吸收事件稀，化学事件必须密。</p><p>CAR 的答案是：光酸产生剂（PAG）在曝光时放出酸，后烘（PEB）期间酸催化保护基团脱落，极性翻转，碱性显影液溶掉曝光区（正胶）。一个酸分子循环多次，剂量可以被「放大」。没有这套循环，上一课的扫描速度写不出产线 wph。</p><p><span class="marginnote">「化学放大」直译过来就是：一次光子事件造出的酸分子，在后烘里像滚雪球一样催化许多次脱保护反应。灵敏度不是靠把每个光子用得更狠，而是靠化学接力把一次事件放大成一片化学事件——这就是「增益」两个字的本义。</span></p><h3 id="空中像、潜像、显影像" tabindex="-1">空中像、潜像、显影像 <a class="header-anchor" href="#空中像、潜像、显影像" aria-label="Permalink to &quot;空中像、潜像、显影像&quot;">​</a></h3><p>曝光结束时，酸的空间分布是潜像，还不是浮雕。PEB 改酸与保护基的分布；显影才切出厚度轮廓。Mack 把三段分开，本课只钉第一段到催化循环：剂量如何变成酸。把 SEM 上的线宽直接叫「曝光结果」，会把后两课的扩散与显影偷运进来。</p><p><span class="marginnote">化学放大是 DUV 的主流，不是「所有胶」。i 线 DNQ、EUV 金属氧化物胶是不同工作点。本课默认 248/193 nm 的 CAR，EUV 分叉在更后面。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方至少含聚合物（带保护基）、PAG、淬灭剂（碱，用来收酸、定阈值）。曝光波长必须落在 PAG 的有效吸收，而不是聚合物随便染色。PEB 温度与时间是催化时钟：太短增益不够，太长等于把后面酸扩散课的扩散核做大。本课把 PEB 当作增益旋钮，不展开扩散方程。</p><p>淬灭剂让未曝光区的酸被中和，陡化潜像的阈值，也设定「要多少剂量才打得过碱」。这是后课衬度曲线的化学前置，这里只承认阈值不完全由光学 \\(I_\\mathrm{th}\\) 决定。</p><h3 id="增益与出气" tabindex="-1">增益与出气 <a class="header-anchor" href="#增益与出气" aria-label="Permalink to &quot;增益与出气&quot;">​</a></h3><p>增益高，灵敏度好，扫描可以快。代价在后面的酸扩散课写：酸的出生位置被放大成一片脱保护云。另一笔立刻到期的账是出气与镜头污染——193 nm 尤其敏感，产线用上层涂层和受控配方，不是本课的成像问题，但禁止把「更敏」写成无条件目标。</p><p><span class="marginnote">数字感受一下增益：假设一个酸分子在 PEB 期间平均催化 100 次脱保护，那么同样一单位剂量留下的化学变化就是「无放大」情形的一百倍量级；要达到同样的脱保护程度，所需曝光剂量大致按这个倍数下降，扫描自然可以更快。</span></p>',16)),(t(),o(n,null,{default:E(()=>[B(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%E5%89%82%E9%87%8F%22%5D%20--%3E%20PAG%5B%22PAG%20%E4%BA%A7%E9%85%B8%22%5D%0A%20%20PAG%20--%3E%20PEB%5B%22PEB%20%E5%82%AC%E5%8C%96%E8%84%B1%E4%BF%9D%E6%8A%A4%22%5D%0A%20%20PEB%20--%3E%20POL%5B%22%E6%9E%81%E6%80%A7%E7%BF%BB%E8%BD%AC%22%5D%0A%20%20POL%20--%3E%20DEV%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%98%BE%E5%BD%B1%22%5D%0A%20%20PEB%20--%3E%20DIFF%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%85%B8%E6%89%A9%E6%95%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"光子（或二次电子，在 EUV 上）把 PAG 打成酸。PEB 提供扩散与反应的活化能，酸作为催化剂不按化学计量消耗——直到被淬灭剂中和或离开反应区。潜像的「亮」是高酸浓度，「暗」是保护基仍在。光学对比度高，酸对比也高；光学对比不够，增益只把模糊的酸分布一起放大。",-1)),a[5]||(a[5]=e("p",null,"上一张图画的是「剂量如何一路走到显影」的整体链路；这里补一张机制细节图，回答另一个问题：淬灭剂凭什么能把剂量差陡化成一个显影阈值。",-1)),(t(),o(n,null,{default:E(()=>[B(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E6%9B%9D%E5%85%89%E5%8C%BA%EF%BC%9A%E9%85%B8%E6%B5%93%E5%BA%A6%E9%AB%98%22%5D%20--%3E%20B%5B%22%E8%84%B1%E4%BF%9D%E6%8A%A4%E8%B6%85%E8%BF%87%E9%98%88%E5%80%BC%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%98%BE%E5%BD%B1%E6%BA%B6%E8%A7%A3%EF%BC%88%E7%BA%BF%E6%9D%A1%E5%A4%84%EF%BC%89%22%5D%0A%20%20D%5B%22%E6%9C%AA%E6%9B%9D%E5%85%89%E5%8C%BA%EF%BC%9A%E6%B7%AC%E7%81%AD%E5%89%82%E6%94%B6%E9%85%B8%22%5D%20--%3E%20E%5B%22%E4%BF%9D%E6%8A%A4%E5%9F%BA%E4%BF%9D%E7%95%99%22%5D%0A%20%20E%20--%3E%20F%5B%22%E6%98%BE%E5%BD%B1%E4%B8%8D%E6%BA%B6%EF%BC%88%E9%97%B4%E9%9A%94%E5%A4%84%EF%BC%89%22%5D%0A%20%20Q%5B%22%E6%B7%AC%E7%81%AD%E5%89%82%E5%BD%93%E9%87%8F%22%5D%20-.%20%22%E9%85%B8%E8%A6%81%E5%85%88%E6%89%93%E8%BF%87%E7%A2%B1%E8%BF%99%E9%81%93%E5%A2%99%22%20.-%3E%20B%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>因此 CAR 不能补零级偏置：它放大的是已经存在的剂量差。上一课程的空中像对比与 \\(k_1\\) 窗口，在这里变成「酸图够不够陡」。后课的 \\(\\gamma\\) 是显影对这张酸图的再一次非线性，不要与本课的化学增益混名。</p><p>PEB 差几摄氏度，同一张空中像的 CD 可以走出规格：CAR 把轨道烘箱做成光刻的一部分。前烘决定残留溶剂和自由体积，间接改后课的扩散，因此涂胶单元与扫描机是一条工艺，不能只优化镜头。</p><p><span class="marginnote">常见误区：以为增益越高越好。实际上增益大意味着酸在「罢工」前催化得更多、走得也更远，线边处的脱保护云更糊——灵敏度是拿边直度和工艺窗口换来的，所以淬灭剂才要出来收酸、把阈值画清楚。</span></p><h3 id="后课默认" tabindex="-1">后课默认 <a class="header-anchor" href="#后课默认" aria-label="Permalink to &quot;后课默认&quot;">​</a></h3><p>说到 DUV 胶，默认正性 CAR：PAG、PEB、淬灭剂。说到灵敏度，默认来自催化循环，不是来自加厚胶。酸扩散长度当作后课才引入的符号，本课不给纳米数当普适常数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 LWR 公式，不写 EUV 光子泊松，不写金属氧化物团簇。也不把 Ito 的早期实验剂量当成今日 ArF 浸没的工艺点。负胶 CAR 存在，机制对称（交联而非脱保护），产线逻辑后段仍以正胶为主，本课不并列开两套百科。</p><p>底层抗反射（BARC）与上层涂层改的是驻波和出气，不改催化循环的定义。它们会出现在工艺窗口里，但本课的对象仍是「剂量如何变成酸」。193 nm 聚合物本身吸收就强，PAG 不是唯一吸收体；把全部吸收算进 PAG 量子产率会高估增益。</p><p><span class="marginnote">Ito 与 Willson 的化学放大把「一个光子许多反应」写进 DUV。后课引用时指向这条链路，不要另造一篇不存在的 arXiv 作为 CAR 的发明文献。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扫描机写下的是剂量；CAR 用 PAG + PEB 催化把剂量写成酸潜像。</li><li>增益买灵敏度，使薄膜 DUV 胶与扫描产能同时成立。</li><li>空中像对比不够，放大帮不上；增益不是 RET。</li><li>酸往哪走、边有多糙，是后面的酸扩散课；显影怎么切，是再后面的显影课。</li><li>出处：Ito &amp; Willson 化学放大；Mack, <em>Fundamental Principles of Optical Lithography</em>；Levinson, <em>Principles of Lithography</em>。</li></ul>',11))])}const F=s(d,[["render",h]]);export{f as __pageData,F as default};
